const hideWebsiteLoader = function () {
    const loader = document.querySelector('.an-loader');

    if (!loader) {
        return;
    }

    loader.classList.add('hide');
    loader.style.pointerEvents = 'none';
};

// #region debug-point top-disappears-runtime
const topDisappearsDebug = (() => {
    const isLocalDebugHost = ['127.0.0.1', 'localhost'].includes(window.location.hostname);
    const endpoint = 'http://127.0.0.1:7777/event';
    let rafId = 0;
    let lastBucket = '';

    const toRect = (element) => {
        if (!element) {
            return null;
        }

        const rect = element.getBoundingClientRect();

        return {
            top: Math.round(rect.top),
            left: Math.round(rect.left),
            width: Math.round(rect.width),
            height: Math.round(rect.height),
        };
    };

    const toElementMeta = (element) => {
        if (!element) {
            return null;
        }

        return {
            tag: element.tagName,
            id: element.id || '',
            className: typeof element.className === 'string'
                ? element.className
                : (element.className && element.className.baseVal) || '',
        };
    };

    const inspectNavLinks = () => {
        return Array.from(document.querySelectorAll('header a'))
            .slice(0, 8)
            .map((link) => {
                const rect = link.getBoundingClientRect();
                const x = Math.round(rect.left + (rect.width / 2));
                const y = Math.round(rect.top + (rect.height / 2));
                const topAtCenter = document.elementFromPoint(x, y);

                return {
                    href: link.getAttribute('href'),
                    rect: toRect(link),
                    center: { x, y },
                    topAtCenter: toElementMeta(topAtCenter),
                    covered: !!topAtCenter && topAtCenter !== link && !link.contains(topAtCenter),
                };
            });
    };

    const send = (point, detail) => {
        if (!isLocalDebugHost) {
            return;
        }

        try {
            fetch(endpoint, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                keepalive: true,
                body: JSON.stringify({
                    sessionId: 'top-disappears',
                    point,
                    href: window.location.href,
                    scrollY: Math.round(window.scrollY),
                    tsClient: Date.now(),
                    detail,
                }),
            }).catch(() => {});
        } catch (_) {}
    };

    const inspect = (phase) => {
        if (!isLocalDebugHost) {
            return;
        }

        const header = document.querySelector('header');
        const slider = document.querySelector('.main-slider');
        const loader = document.querySelector('.an-loader');
        const topElement = document.elementFromPoint(
            Math.max(0, Math.round(window.innerWidth / 2)),
            12
        );
        const headerStyle = header ? window.getComputedStyle(header) : null;
        const sliderStyle = slider ? window.getComputedStyle(slider) : null;
        const loaderStyle = loader ? window.getComputedStyle(loader) : null;

        send('top-state', {
            phase,
            htmlClass: document.documentElement.className,
            bodyClass: document.body.className,
            topElement: toElementMeta(topElement),
            navLinks: inspectNavLinks(),
            header: {
                exists: !!header,
                rect: toRect(header),
                display: headerStyle ? headerStyle.display : null,
                visibility: headerStyle ? headerStyle.visibility : null,
                opacity: headerStyle ? headerStyle.opacity : null,
                position: headerStyle ? headerStyle.position : null,
                zIndex: headerStyle ? headerStyle.zIndex : null,
                transform: headerStyle ? headerStyle.transform : null,
            },
            slider: {
                exists: !!slider,
                rect: toRect(slider),
                backgroundColor: sliderStyle ? sliderStyle.backgroundColor : null,
                opacity: sliderStyle ? sliderStyle.opacity : null,
                transform: sliderStyle ? sliderStyle.transform : null,
            },
            loader: {
                exists: !!loader,
                className: loader ? loader.className : null,
                display: loaderStyle ? loaderStyle.display : null,
                visibility: loaderStyle ? loaderStyle.visibility : null,
                pointerEvents: loaderStyle ? loaderStyle.pointerEvents : null,
                rect: toRect(loader),
            },
        });
    };

    const scheduleInspect = (phase) => {
        if (!isLocalDebugHost) {
            return;
        }

        if (rafId) {
            cancelAnimationFrame(rafId);
        }

        rafId = window.requestAnimationFrame(() => inspect(phase));
    };

    const onScroll = () => {
        if (!isLocalDebugHost) {
            return;
        }

        const bucket = window.scrollY <= 10
            ? 'at-top'
            : window.scrollY <= 150
                ? 'near-top'
                : 'away-from-top';

        if (bucket === lastBucket) {
            return;
        }

        lastBucket = bucket;
        scheduleInspect(`scroll:${bucket}`);
    };

    document.addEventListener('pointerdown', (event) => {
        const anchor = event.target.closest ? event.target.closest('a') : null;

        send('pointerdown', {
            x: Math.round(event.clientX),
            y: Math.round(event.clientY),
            target: toElementMeta(event.target),
            anchor: anchor ? {
                href: anchor.getAttribute('href'),
                text: (anchor.textContent || '').trim().slice(0, 80),
            } : null,
            topAtPoint: toElementMeta(document.elementFromPoint(event.clientX, event.clientY)),
        });
    }, true);

    document.addEventListener('click', (event) => {
        const anchor = event.target.closest ? event.target.closest('a') : null;

        send('click', {
            x: Math.round(event.clientX),
            y: Math.round(event.clientY),
            target: toElementMeta(event.target),
            anchor: anchor ? {
                href: anchor.getAttribute('href'),
                text: (anchor.textContent || '').trim().slice(0, 80),
            } : null,
            defaultPrevented: event.defaultPrevented,
        });
    }, true);

    return { inspect, onScroll };
})();
// #endregion

document.addEventListener('DOMContentLoaded', hideWebsiteLoader, { once: true });
document.addEventListener('DOMContentLoaded', () => topDisappearsDebug.inspect('dom-content-loaded'), { once: true });
window.addEventListener('load', hideWebsiteLoader, { once: true });
window.addEventListener('load', () => topDisappearsDebug.inspect('window-load'), { once: true });
window.addEventListener('pageshow', () => topDisappearsDebug.inspect('page-show'));
window.addEventListener('pageshow', hideWebsiteLoader);
window.addEventListener('scroll', topDisappearsDebug.onScroll, { passive: true });
window.addEventListener('resize', () => topDisappearsDebug.inspect('resize'));
setTimeout(hideWebsiteLoader, 300);
// Script for Counter
$(document).ready(function () {
    $('.minus').click(function () {
        var $input = $(this).parent().find('input');
        var count = parseInt($input.val()) - 1;
        count = count < 1 ? 1 : count;
        $input.val(count);
        $input.change();
        return false;
    });
    $('.plus').click(function () {
        var $input = $(this).parent().find('input');
        $input.val(parseInt($input.val()) + 1);
        $input.change();
        return false;
    });
});

$('.circleBtn').click(function () {
    $(this).toggleClass('active')
});

// Keep WOW disabled on the website; it was hiding shared sections.

$('.product_slider').slick({
    dots: false,
    infinite: true,
    arrows: true,
    speed: 300,
    slidesToShow: 1,
    slidesToScroll: 1,
});

/* Store the element in el */
let el = document.getElementById('tilt')

/* Make sure the element exists */
if (el) {
  /* Get the height and width of the element */
  const height = el.clientHeight;
  const width = el.clientWidth;

  /*
   * Add a listener for mousemove event
   * Which will trigger function 'handleMove'
  */
  el.addEventListener('mousemove', function handleMove(e) {
    const xVal = e.layerX;
    const yVal = e.layerY;

    const yRotation = 20 * ((xVal - width / 2) / width);
    const xRotation = -20 * ((yVal - height / 2) / height);

    const transformString = `perspective(500px) scale(1.1) rotateX(${xRotation}deg) rotateY(${yRotation}deg)`;

    el.style.transform = transformString;
  });

  /* Add listener for mouseout event, remove the rotation */
  el.addEventListener('mouseout', function () {
    el.style.transform = 'perspective(500px) scale(1) rotateX(0) rotateY(0)';
  });

  /* Add listener for mousedown event, to simulate click */
  el.addEventListener('mousedown', function () {
    el.style.transform = 'perspective(500px) scale(0.9) rotateX(0) rotateY(0)';
  });

  /* Add listener for mouseup, simulate release of mouse click */
  el.addEventListener('mouseup', function () {
    el.style.transform = 'perspective(500px) scale(1.1) rotateX(0) rotateY(0)';
  });

} else {
  console.warn("Element with ID 'tilt' not found");
}
